        connection.execute("INSERT INTO sessions(sid,user,expires) VALUES(?,?,?)",(new_sid,user,expires))
    return new_sid
def resolve(connection,sid,now):
    row=connection.execute("SELECT user,expires FROM sessions WHERE sid=?",(sid,)).fetchone()
